# Let me try yet another rule: sum of indices forces a "center"

def get_boundary(left, right):
    ones = [c for c in range(4) if left[c] == 1]
    twos = [c for c in range(4) if right[c] == 2]

    if not ones and not twos:
        return 0  # no boundary

    # Center of mass for ones and twos
    ones_cm = sum(ones) / len(ones) if ones else 0
    twos_cm = sum(twos) / len(twos) if twos else 0

    # Boundary position: between 0-3 based on which comes first
    if ones_cm <= twos_cm and ones:
        return min(twos) if twos else len(ones)
    elif twos_cm < ones_cm and twos:
        return min(ones) if ones else len(twos)
    else:
        # Tie at same center
        return len(ones) if ones else len(twos)

